class SagaOrchestrator:
    def __init__(self, store, bus):
        self.store = store  # durable saga log
        self.bus = bus

    def run(self, saga_id, steps):
        # steps: list of (forward_fn, compensate_fn)
        completed = self.store.load(saga_id)  # must survive crash
        for i, (forward, compensate) in enumerate(steps):
            if i < len(completed):
                continue  # already done, do not re-execute blindly
            try:
                # forward must be idempotent on saga_id + step index
                forward(key=f"{saga_id}:{i}")
                self.store.append(saga_id, i)
            except Exception:
                self.compensate(saga_id, steps, completed)
                return False
        return True

    def compensate(self, saga_id, steps, completed):
        # reverse order, each idempotent and retried with backoff
        for i in reversed(completed):
            _, compensate = steps[i]
            self.bus.enqueue_retry(
                fn=compensate, key=f"{saga_id}:{i}:comp",
                max_retries="infinite until acked + alert"
            )
